/*
 * Documentation-grade semantic C for E15's resident post-FMV continuations.
 *
 * This is not a matching-source claim.  The exhaustive fmv_bin_load call
 * census, exact continuation windows, pristine byte hashes, direct edges and
 * hash-pinned ASM owners are regenerated by
 * tools/phase4_fmv_lifecycle_continuations.py.
 */
#include <stdint.h>

extern void fmv_bin_load(int selector, int transition_hook_enabled);
extern void scene_setup_and_load(int scene, int transition);
extern void level_transition_orchestrator(int transition);
extern void display_buffers_init(void);
extern void scene_load_init(void);

#define SHELL_SUBSTATE       (*(volatile uint32_t *)0x8008243Cu)
#define SCENE_FLOW_STATE     (*(volatile uint32_t *)0x8008264Cu)
#define LEVEL_PROGRESS_BASE  ((volatile uint8_t *)0x80087FE3u)
#define LEVEL_A_TRANSITION_0 (*(volatile uint16_t *)0x80082388u)
#define LEVEL_A_TRANSITION_1 (*(volatile uint16_t *)0x80082494u)
#define LEVEL_A_TRANSITION_2 (*(volatile uint16_t *)0x80082430u)

/*
 * The matching resident wrapper at 0x8003E7C0..0x8003E83C owns the overlay
 * load/player/display boundary for every call below.  It unconditionally
 * calls the by-name loader at 0x8003E7FC with "fmv\\fmv.bin" and destination
 * 0x800B5788, invokes the synchronous FMV player at 0x8003E814, then calls the
 * post-player display initializer at 0x8003E81C before returning.  Therefore
 * repeated calls recopy the same overlay bytes; an unchanged Region-B hash
 * across two movies is not proof that no reload occurred.
 *
 * The wrapper contains no explicit Region-B unload or clear.  Common player
 * teardown ends transient FMV use, but later Region-B replacement belongs to
 * the classified resident return continuation or another overlay loader.
 * Endpoint non-residency alone does not identify that overwrite instruction.
 */

/*
 * Cold boot is one synchronous owner, not three detached calls.  It plays
 * DLOGO, TITLE and INTRO in sequence, then initializes scene-flow state before
 * reaching the six-way shell dispatch documented in
 * fmv_callback_consumer_frontier.c.
 */
static void boot_movie_chain(void)
{
    fmv_bin_load(1, 0);
    fmv_bin_load(0, 0);
    fmv_bin_load(45, 0);
    scene_setup_and_load(0, 0);
}

/*
 * The scene-flow owner selects a bonus movie from one u8 cursor, publishes its
 * return state, and continues the owner's loop.  Static code proves that
 * continuation; it does not prove movie-viewer selection or unlock policy.
 */
static void bonus_clip_return(int selector, uint32_t return_state)
{
    fmv_bin_load(selector, -1);
    SCENE_FLOW_STATE = return_state;
}

/* The game-over LOSE continuation is an exact call contract. */
static void game_over_lose_return(void)
{
    fmv_bin_load(46, 0);
    scene_setup_and_load(5, 64);
}

/*
 * Natural LOSE Region-B replacement ownership is narrower than the generic
 * continuation above.  The observed pristine return at 0x800500E0 calls
 * scene_setup_and_load(5, 64).  Because transition 64 is not -1, that owner
 * runs display initialization and then resource_id_dat_load_dispatcher(0).
 * The selector-zero branch at 0x8003D300 materializes "bits\\memory.bin" and
 * destination 0x800B5788, then reaches universal_file_loader and CdRead.
 *
 * E16 owns those replacement bytes.  C16 owns this game-over transition
 * choice; E14 viewer/save policy does not intersect the selected path.  The
 * static chain proves the first replacement request after this return, but
 * does not prove the first CD/DMA write cycle, transfer failure behavior, or
 * any completed-level/movie-viewer continuation.
 */

/*
 * Completed-Level-B Region-B replacement ownership is a separate conditional
 * scene-flow policy.  The retained natural selector-11 player returns at
 * 0x80050324 with the scene-flow entry state still in s0 as one.  That joins
 * the selected invocation to the state-one call at 0x8005013C and its
 * continuation at 0x80050144.
 *
 * The completed-level owner reads the 16-byte progress table and publishes
 * scene-flow value zero.  Only the all-complete sum 112 branch reloads
 * selector 41 in the same FMV.BIN and publishes value one; this is not a
 * Region-B replacement.  On return, the resident scene-flow dispatcher owns
 * the next replacement request.  A negative pending request calls
 * scene_setup_and_load(3, 0) at 0x8004FD74; a nonnegative request calls
 * scene_setup_and_load(6, 128) at 0x8005029C.  Both transition values differ
 * from the -1 resource-skip sentinel, so both execute the same selector-zero
 * "bits\\memory.bin" request at destination 0x800B5788.
 *
 * E16 therefore owns the replacement bytes while resident scene flow owns
 * the completed-level transition choice.  The ordinary progress scan does
 * not call the save serializer or write the C17 movie-viewer unlock byte at
 * 0x8009B889.  The all-complete branch does set the adjacent scene flag at
 * 0x8009B888; whether that flag is serialized remains E14/C17 debt.  This
 * static policy still does not prove the first CD/DMA write cycle or any
 * movie-viewer return.
 */

/* LEV15C hands control to the level-transition owner with transition zero. */
static void finale_c_return(void)
{
    fmv_bin_load(40, 0);
    level_transition_orchestrator(0);
}

/*
 * Each completed-level-B selector returns to one progress scan.  The owner
 * sums the exact 16-byte completion table.  A total of 112 selects LEV15D;
 * every other total publishes the ordinary scene-flow return state.
 */
static void completed_level_b_return(int selector)
{
    unsigned sum = 0;
    unsigned index;

    fmv_bin_load(selector, -1);
    for (index = 0; index != 16; ++index)
        sum += LEVEL_PROGRESS_BASE[index];
    if (sum == 112)
        fmv_bin_load(41, -1);
    else
        SCENE_FLOW_STATE = 0;
}

/*
 * LEV15D publishes transition value one and returns through the same
 * completion owner.  It is a separate continuation window from the Level-B
 * progress scan.
 */
static void finale_d_return(void)
{
    fmv_bin_load(41, -1);
    SCENE_FLOW_STATE = 1;
}

/*
 * The Level-A call returns inside the full 0x8005B714..0x8005BC64 reset
 * owner.  Its first continuation clears three transition fields before
 * display and scene initialization.  The retained machine artifact guards all
 * 20 direct calls through the owner's true end, not only this abbreviated
 * semantic sketch.
 */
static void level_a_reset_return(int selector)
{
    fmv_bin_load(selector, 0);
    LEVEL_A_TRANSITION_0 = 0;
    LEVEL_A_TRANSITION_1 = 0;
    LEVEL_A_TRANSITION_2 = 0;
    display_buffers_init();
    scene_load_init();
}

/*
 * The transient player owns the pre-return lifecycle.  Its two completion
 * writers are 0x800B6B24 (frame-order regression) and 0x800B6B48
 * (selected-limit threshold); the sole player-loop reader is 0x800B743C.
 * Frame-limit, decode-stop, resident-exit, input-sentinel and completion paths
 * converge at 0x800B7464.  The common teardown issues CdControl(Pause=0x0b),
 * stops presentation, clears the ring and callbacks, frees all three
 * allocations, restores the 0x908-byte frame and returns normally.
 *
 * Decode-record absence is owned by 0x800B6C24..0x800B6CA4 and publishes the
 * u8 stop latch at 0x800B6C84.  Decode polling is bounded by the 0x00800000
 * counter in 0x800B6CA4..0x800B6D68.  File-open failure and the GetlocP/Read2
 * submission retries are inside the same transient player frontier.  These
 * exact owners establish routing and convergence, but not native frequency or
 * the user-visible result of an induced media failure.
 */

/*
 * The resident CD initializer at 0x80045D6C registers callback 0x80045D5C
 * with OpenEvent for exact event class 0xF0000003/spec 0x8000, then enables
 * the retained event handle.  The matching callback stores u32 value 1 at
 * resident field 0x80082484 (gp+0x6ec).  During playback, 0x800B7420 reads
 * that exact address and 0x800B7428 compares it with the value-1 sentinel
 * established at 0x800B70D8.  Equality branches to 0x800B7464, the existing
 * CdControl(0x0b) and common-teardown block.
 *
 * This closes the static registration -> callback store -> player consumer ->
 * Pause/teardown route.  It does not establish whether or how often native
 * delivery occurs, the Pause command result, or the user-visible outcome of a
 * media failure.  Those facts require the separately declared same-anchor
 * native control.  Malformed-stream behavior and C17/E14 viewer/persistence
 * policy remain separate contracts.
 */

/*
 * Five exact post-helper predicates partition the remaining player decision:
 * decode-stop latch at 0x800B7294, resident CD-event value one at
 * 0x800B7428, controller-derived countdown twelve at 0x800B7430, completion
 * request value one at 0x800B7444, and decoded-index/selected-limit comparison
 * at 0x800B745C.  The controller predicate is sourced by resident poll
 * 0x8003A2DC and exact mask 0x4008; it is not an untyped overlay field.
 *
 * Completion alone enters 0x800B6E38 and issues command 8 before command 11.
 * Every other exit enters the command-11/common-teardown route directly.
 * These static facts classify command and branch ownership, not native
 * delivery frequency, malformed-stream outcome, or frontend pause behavior.
 */
